{'venues': [{'name': 'Criterion Theatre', 'type': 'venue', 'id': 'KovZ9177AZ0', 'test': False, 'url': 'https://www.ticketmaster.co.uk/criterion-theatre-tickets-london/venue/254089', 'locale': 'en-us', 'distance': 0.3, 'units': 'MILES', 'postalCode': 'W1J 9HT', 'timezone': 'Europe/London', 'city': {'name': 'London'}, 'country': {'name': 'Great Britain', 'countryCode': 'GB'}, 'address': {'line1': '218 - 223 PICCADILLY'}, 'location': {'longitude': '-0.13372400', 'latitude': '51.50970700'}, 'markets': [{'name': 'All of United Kingdom', 'id': '201'}, {'name': 'London', 'id': '202'}, {'name': 'South', 'id': '203'}], 'dmas': [{'id': 601}, {'id': 602}, {'id': 603}], 'boxOfficeInfo': {'phoneNumberDetail': '033 33 202 895', 'openHoursDetail': 'Tuesday - Saturday 10am to 8pm, Sundays 11.30am to 7.30pm', 'willCallDetail': 'Collect tickets within the hour before curtain up. Please take the card used to purchase the tickets and the Ticketmaster reference number.'}, 'parkingDetail': 'There is limited street parking around the area with pay and display charges. Please note that resident parking bays are not available for visitor parking. The Congestion Charge is currently operational Monday to Sunday 7am - 10pm, including Bank Holidays. The nearest car park is: Q-Park Leicester Square Whitcomb Street London WC2H 7DT', 'accessibleSeatingDetail': 'The auditorium is situated below street level with step free access only available to the Upper Circle. Dress Circle is one further level down and the Stalls three levels below Jermyn Street level, and four floors below Piccadilly Circus. Via the main entrance stairway there are 23 steps down to the Upper Circle, 32 steps down to the Dress Circle and 54 steps to the Stalls. Unfortunately we do not currently have a lift facility in the Grade II listed building. We can offer alternative access via our fire exit stairways to all levels via Jermyn Street upon request. Although there are still steps they are reduced and are not part of the ornate curved stairway of our main entrance. Please speak to a member of our front of house team on arrival or contact us on 020 7839 8811 in advance of your visit.', 'generalInfo': {'generalRule': 'Please note that bag checks are carried out for all patrons prior to their entry into the Foyer/Box Office. We would advise patrons to arrive no later than 15 minutes prior to the performance start time to allow for the extra security checks. If you are bringing a group with you please ensure that all members of your group are aware of the bag check procedure and the recommended time to arrive to the theatre. We very much appreciate patrons having their bags open as they reach our bag check staff member as it significantly speeds up the process for everyone involved. We are not able to accommodate large bags or suitcases and advise patrons to bring with them only essential, handbag size, bags. Only valid ticket holders will be admitted to the theatre. Please note that we do not allow any hot food or alcohol purchased outside of the venue into the theatre. If you have alcohol with you these items can be kept at the Box Office for the duration of the performance and collected as you leave. Please make the staff member conducting the bag checks aware.', 'childRule': 'No babes in arms. Young children are admitted but not encouraged unless the parent is confident that the child is old enough to be attentive to the performance and not a distraction for other members of the audience. Everyone must have a valid ticket and occupy a seat. Accompanying adults will be asked to remove any noisy infants.'}, 'upcomingEvents': {'tmc': 202, '_total': 202, '_filtered': 0}, 'ada': {'adaPhones': 'Box office 033 33 202 895', 'adaCustomCopy': 'To better accommodate your needs, Criterion Theatre has requested that all special seating accommodations be solicited only through their representatives. Please contact a Criterion Theatre representative for further help with your ticket purchase.*   Advance ticket purchase may be required.

* Box office information is subject to change.', 'adaHours': 'In Person:  Tuesday - Saturday 12 noon to 8pm, Sundays 12 noon to 7.30pm

By Telephone: Tuesday - Saturday 10am to 8pm, Sundays 11.30am to 7.30pm'}, '_links': {'self': {'href': '/discovery/v2/venues/KovZ9177AZ0?locale=en-us'}}}], 'attractions': [{'name': 'Titanique', 'type': 'attraction', 'id': 'K8vZ917qa5V', 'test': False, 'url': 'https://www.ticketmaster.co.uk/titanique-tickets/artist/5482959', 'locale': 'en-us', 'externalLinks': {'homepage': [{'url': 'https://titaniquemusical.com/'}]}, 'images': [{'ratio': '16_9', 'url': 'https://s1.ticketm.net/dam/a/1f2/3812eff6-4904-4d2b-a9a7-32df4bee31f2_TABLET_LANDSCAPE_16_9.jpg', 'width': 1024, 'height': 576, 'fallback': False}, {'ratio': '16_9', 'url': 'https://s1.ticketm.net/dam/a/1f2/3812eff6-4904-4d2b-a9a7-32df4bee31f2_RECOMENDATION_16_9.jpg', 'width': 100, 'height': 56, 'fallback': False}, {'ratio': '16_9', 'url': 'https://s1.ticketm.net/dam/a/1f2/3812eff6-4904-4d2b-a9a7-32df4bee31f2_SOURCE', 'width': 2426, 'height': 1365, 'fallback': False}, {'ratio': '16_9', 'url': 'https://s1.ticketm.net/dam/a/1f2/3812eff6-4904-4d2b-a9a7-32df4bee31f2_EVENT_DETAIL_PAGE_16_9.jpg', 'width': 205, 'height': 115, 'fallback': False}, {'ratio': '16_9', 'url': 'https://s1.ticketm.net/dam/a/1f2/3812eff6-4904-4d2b-a9a7-32df4bee31f2_RETINA_PORTRAIT_16_9.jpg', 'width': 640, 'height': 360, 'fallback': False}, {'ratio': '4_3', 'url': 'https://s1.ticketm.net/dam/a/1f2/3812eff6-4904-4d2b-a9a7-32df4bee31f2_CUSTOM.jpg', 'width': 305, 'height': 225, 'fallback': False}, {'ratio': '16_9', 'url': 'https://s1.ticketm.net/dam/a/1f2/3812eff6-4904-4d2b-a9a7-32df4bee31f2_TABLET_LANDSCAPE_LARGE_16_9.jpg', 'width': 2048, 'height': 1152, 'fallback': False}, {'ratio': '3_2', 'url': 'https://s1.ticketm.net/dam/a/1f2/3812eff6-4904-4d2b-a9a7-32df4bee31f2_RETINA_PORTRAIT_3_2.jpg', 'width': 640, 'height': 427, 'fallback': False}, {'ratio': '3_2', 'url': 'https://s1.ticketm.net/dam/a/1f2/3812eff6-4904-4d2b-a9a7-32df4bee31f2_TABLET_LANDSCAPE_3_2.jpg', 'width': 1024, 'height': 683, 'fallback': False}, {'ratio': '16_9', 'url': 'https://s1.ticketm